import Foundation
import NIO
import NIOHTTP1

// ML Inference Server with async/await concurrency
// Handles tensor operations for real-time prediction

struct TensorShape {
    let dimensions: [Int]
    var totalElements: Int {
        dimensions.reduce(1, *)
    }
}

actor ModelRegistry {
    private var models: [String: InferenceModel] = [:]

    func register(_ model: InferenceModel, name: String) {
        models[name] = model
    }

    func getModel(_ name: String) -> InferenceModel? {
        return models[name]
    }
}

class InferenceModel {
    let layerCount: Int
    let maxBatchSize: Int
    private let weightsBuffer: UnsafeMutableBufferPointer<Float>

    init(layers: Int, maxBatch: Int) {
        self.layerCount = layers
        self.maxBatchSize = maxBatch
        let size = layers * 1024 * 1024
        self.weightsBuffer = .allocate(capacity: size)
        weightsBuffer.initialize(repeating: 0.0)
    }

    deinit {
        weightsBuffer.deallocate()
    }
}

struct InferenceRequest {
    let modelName: String
    let inputShape: TensorShape
    let batchSize: Int
    let recursionDepth: Int
}

let kMaxRecursionDepth = 64
let kMaxWorkspaceElements = 4 * 1024 * 1024  // 4M floats = 16MB max

// Core inference pipeline with iterative layer processing
func processLayerIterative(
    totalLayers: Int,
    inputData: UnsafeMutablePointer<Float>,
    outputData: UnsafeMutablePointer<Float>,
    workspaceSize: Int,
    batchSize: Int
) async -> Bool {
    // Guard against zero/negative workspace to avoid modulo-by-zero and invalid allocation
    guard workspaceSize > 0 && batchSize > 0 else {
        return false
    }

    // Use fixed-size workspace, process layers iteratively
    let activationSize = min(workspaceSize * batchSize, kMaxWorkspaceElements)

    guard activationSize > 0 else {
        return false
    }

    let activationBuffer = UnsafeMutableBufferPointer<Float>.allocate(capacity: activationSize)
    defer { activationBuffer.deallocate() }
    activationBuffer.initialize(repeating: 0.0)

    var currentInput = inputData

    for layerIndex in 0..<totalLayers {
        // Simulate matrix multiply for this layer
        for i in 0..<min(activationSize, activationBuffer.count) {
            activationBuffer[i] = currentInput[i % workspaceSize] * 0.99
        }

        if layerIndex < totalLayers - 1 {
            // Swap buffers - no recursion needed
            for i in 0..<min(workspaceSize, activationBuffer.count) {
                currentInput[i] = activationBuffer[i]
            }
        } else {
            // Copy final output
            for i in 0..<min(workspaceSize, activationBuffer.count) {
                outputData[i] = activationBuffer[i]
            }
        }

        // Yield to cooperative scheduler periodically
        if layerIndex % 8 == 0 {
            await Task.yield()
        }
    }

    return true
}

func computeWorkspaceSize(shape: TensorShape, depth: Int) -> Int {
    // Workspace scales with input dimensions, capped for safety
    let baseSize = shape.totalElements
    let scaleFactor = min(max(depth, 1), kMaxRecursionDepth)
    let result = baseSize * scaleFactor
    return min(result, kMaxWorkspaceElements)
}

func handleInference(request: InferenceRequest, registry: ModelRegistry) async throws -> [Float] {
    guard let model = await registry.getModel(request.modelName) else {
        throw InferenceError.modelNotFound
    }

    // Validate batch size against model maximum and enforce a positive lower bound
    guard request.batchSize >= 1 && request.batchSize <= model.maxBatchSize else {
        throw InferenceError.batchTooLarge
    }

    // Validate recursion depth - enforce strict upper bound
    guard request.recursionDepth >= 0 && request.recursionDepth <= kMaxRecursionDepth else {
        throw InferenceError.invalidDepth
    }

    // Compute workspace with enforced bounds
    let workspaceSize = computeWorkspaceSize(
        shape: request.inputShape,
        depth: request.recursionDepth
    )

    // Reject empty / zero-sized workspace to avoid modulo-by-zero and invalid allocations
    guard workspaceSize > 0 else {
        throw InferenceError.invalidShape
    }

    // Total layers capped at model layers + bounded user depth
    let effectiveLayers = min(
        model.layerCount + request.recursionDepth,
        model.layerCount + kMaxRecursionDepth
    )

    let inputBuffer = UnsafeMutableBufferPointer<Float>.allocate(capacity: workspaceSize)
    defer { inputBuffer.deallocate() }
    inputBuffer.initialize(repeating: 1.0)

    let outputBuffer = UnsafeMutableBufferPointer<Float>.allocate(capacity: workspaceSize)
    defer { outputBuffer.deallocate() }
    outputBuffer.initialize(repeating: 0.0)

    // Iterative layer processing - no recursive stack growth
    let success = await processLayerIterative(
        totalLayers: effectiveLayers,
        inputData: inputBuffer.baseAddress!,
        outputData: outputBuffer.baseAddress!,
        workspaceSize: workspaceSize,
        batchSize: request.batchSize
    )

    guard success else {
        throw InferenceError.computationFailed
    }

    return Array(outputBuffer)
}

enum InferenceError: Error {
    case modelNotFound
    case batchTooLarge
    case computationFailed
    case invalidDepth
    case invalidShape
}

// Server entry point
@main
struct MLServer {
    static func main() async throws {
        let registry = ModelRegistry()
        let defaultModel = InferenceModel(layers: 12, maxBatch: 64)
        await registry.register(defaultModel, name: "transformer-v1")

        print("ML Inference Server started on port 8080")
